{
  "actions": [
    {
      "action": "Preserve arrival order across every reroute",
      "mechanism": "Separate a case’s permanent waiting claim from its current team, tags, and queue location.",
      "implementation": "Store immutable arrival_at and intake_sequence. Rank eligible, ready cases within each explicit urgency tier by that pair, never by transfer time.",
      "check": "Reroute an older case twice; verify it still precedes newer eligible cases. Simultaneous arrivals must retain deterministic intake order.",
      "risk": "Urgency tiers can starve ordinary cases; monitor their oldest waits."
    },
    {
      "action": "Enforce eligibility when assignments commit",
      "mechanism": "Treat required language, product expertise, urgent qualification, and current roster capacity as assignment gates.",
      "implementation": "Route automatic and manual assignments through one transaction that rechecks worker qualifications, roster version, and remaining capacity before reserving a slot.",
      "check": "Race two assignments for one slot and change shifts during dispatch; reject over-capacity, off-shift, language-mismatched, and unqualified urgent assignments.",
      "risk": "Stale qualification records can invalidate otherwise correct routing."
    },
    {
      "action": "Show why each case is waiting",
      "mechanism": "Represent missing information and unavailable skills separately instead of hiding both behind an unassigned label.",
      "implementation": "Record independent blockers for information, skill coverage, and capacity. Display missing fields, required skills, blocker age, and total age from arrival.",
      "check": "Create cases with each blocker and both information and skill blockers; verify every reason appears and clearing one preserves the others.",
      "risk": "Overly broad information requirements can unnecessarily block service."
    },
    {
      "action": "Correct tags without recreating cases",
      "mechanism": "Version routing requirements on the original case, preserving its waiting claim while preventing assignments based on superseded tags.",
      "implementation": "Apply tag corrections atomically; retain arrival fields, record old and new values, invalidate pending offers, and requeue incompatible active assignments.",
      "check": "Correct language while an offer is accepted; only an assignment matching the latest requirements may commit, with original arrival unchanged.",
      "risk": "Repeated corrections can interrupt work; retain notes and correction history."
    },
    {
      "action": "Hold urgent cases safely when coverage disappears",
      "mechanism": "Make missing urgent coverage an explicit escalation condition, never permission to relax qualification requirements.",
      "implementation": "Require documented issue-based urgency criteria, excluding status and spending. With neither trained worker available, hold by original arrival and alert the shift lead.",
      "check": "Run a shift with no eligible urgent worker: no assignment occurs. Adding qualified coverage releases eligible cases in preserved order.",
      "risk": "Escalation cannot guarantee immediate qualified coverage or response."
    },
    {
      "action": "Reserve scarce skills through batch matching",
      "mechanism": "Consider workers together so flexible staff do not consume work that available specialists could handle.",
      "implementation": "Build eligible case-worker edges from the roster. Select cases by urgency and original arrival, then prefer least-flexible eligible workers without displacing older feasible cases.",
      "check": "Submit simultaneous cases needing different skills; verify a feasible two-worker matching is used and an older feasible case is not skipped.",
      "risk": "Matching rules need deterministic ties and bounded computation."
    },
    {
      "action": "Protect return from waiting for information",
      "mechanism": "Keep the original service claim while temporarily excluding cases that cannot progress without specific customer information.",
      "implementation": "Require a named missing item and next review time before applying the blocker. Remove it when resolved, returning the case using original arrival order.",
      "check": "Resume an older information-blocked case beside newer eligible cases; confirm its original position and that unrelated cases progressed during its absence.",
      "risk": "Unnecessary blockers can conceal delays; audit reasons and durations."
    }
  ],
  "abstention_reason": ""
}
